import * as M from './model.mjs';
const H=3600000,D=24*H,T=Date.parse('2026-10-12T09:30:00+08:00');
export function upgrade(s){
 if(s.ownerSchema===1)return s;
 s.vehicles=s.vehicles||[];s.benefits=s.benefits||[];s.serviceRecords=s.serviceRecords||[];s.quotes=s.quotes||[];
 const samples=[['V01','L002','E3 2022 长续航','DEMO-VIN-123456',42600,true],['V02','L002','City 2019','DEMO-VIN-456789',86000,false],['V03','L008','E5 2023','DEMO-VIN-778899',23800,true],['V04','L005','E3 2021','DEMO-VIN-667788',null,null],['V05','L006','E3 2020','DEMO-VIN-990011',65000,true]];
 for(const [id,lead,model,vin,mileage,relation] of samples){if(!s.leads.some(l=>l.id===lead))continue;s.vehicles.push({id,lead,model,vin,mileage,relation,relationship:relation===true?'当前持有':relation===false?'曾经持有':'关系待核实',relationSource:'模拟车主关系表',mileageAt:mileage===null?null:T,updated:T,tradeIntent:'待确认',intentNote:'',inspection:null,rescueOpen:false});
 const l=s.leads.find(l=>l.id===lead);l.existingOwner=true;
 if(relation!==false){s.benefits.push({id:'B'+id+'W',vehicle:id,name:'车辆保修',kind:'warranty',contract:'DEMO-W-'+id,scope:'指定部件维修；需先核对故障项目',excluded:'易损件、保养与事故损伤不在此模拟保修范围',start:T-2*365*D,end:T+(id==='V03'?10:180)*D,maxMileage:60000,limit:null,used:null,verifiedAt:id==='V01'||id==='V05'?T:null,source:'模拟保障合同 v1',verification:'',deduction:0});s.benefits.push({id:'B'+id+'R',vehicle:id,name:'道路救援',kind:'rescue',contract:'DEMO-R-'+id,scope:'演示地域内50公里拖车，实际服务须确认',excluded:'超出范围或超里程需另行确认',start:T-180*D,end:T+90*D,maxMileage:null,limit:2,used:id==='V04'?null:1,verifiedAt:id==='V04'?null:T,source:'模拟救援方案 v1',verification:'',deduction:0});s.benefits.push({id:'B'+id+'I',vehicle:id,name:'现车检测抵扣',kind:'inspection',contract:'DEMO-I-'+id,scope:'本次现车检测费用，最多抵扣300元',excluded:'不抵扣新车价格，不自动转给其他车辆',start:T-30*D,end:T+45*D,maxMileage:null,limit:1,used:0,verifiedAt:id==='V01'||id==='V05'?T:null,source:'模拟检测权益 v1',verification:'',deduction:300});}
 if(id!=='V04'){s.serviceRecords.push({id:'SR-'+id+'-1',vehicle:id,kind:'保养',at:T-70*D,mileage:Math.max(0,(mileage||0)-4000),title:'常规保养与制动检查',status:'已完成',source:'模拟 Service Record',note:'记录仅覆盖所提供服务，不代表完整车况报告'});s.serviceRecords.push({id:'SR-'+id+'-2',vehicle:id,kind:'道路救援',at:T-120*D,mileage:Math.max(0,(mileage||0)-6000),title:'轮胎故障拖车',status:'已完成',source:'模拟救援事件',note:'不据此推断车辆事故或质量等级'});s.serviceRecords.push({id:'SR-'+id+'-3',vehicle:id,kind:'Warranty 使用',at:T-40*D,mileage:Math.max(0,(mileage||0)-2000),title:'车窗控制模块维修',status:'已结案',source:'模拟保修记录',note:'单次使用不代表保修整体耗尽'});}
 }
 s.ownerSchema=1;return s;
}
export const vehiclesFor=(s,id)=>s.vehicles.filter(v=>v.lead===id);
export const currentVehicles=(s,id)=>vehiclesFor(s,id).filter(v=>v.relation!==false);
export function vehicle(s,id){const v=s.vehicles.find(v=>v.id===id);if(!v)throw Error('车辆不存在');return v;}
function access(s,v){const l=s.leads.find(l=>l.id===v.lead);if(s.user!=='mgr'&&l.owner!==s.user)throw Error('仅当前负责人或主管可处理');return l;}
const requireText=(x,label)=>{if(!x?.trim())throw Error('请填写'+label);return x.trim();};
export function benefitState(s,b){const v=vehicle(s,b.vehicle);if(v.relation===false)return {state:'不适用',reason:'已非当前持有，不能沿用原车主权益'};if(v.relation!==true)return {state:'待核实',reason:'车主关系尚未确认'};if(s.now<b.start)return {state:'未生效',reason:'尚未到合同开始时间'};if(s.now>=b.end)return {state:'已到期',reason:'已达到合同时间期限'};if(b.maxMileage!==null&&(v.mileage===null||s.now-v.mileageAt>30*D))return {state:'待核实',reason:'缺少30天内的有效里程'};if(b.maxMileage!==null&&v.mileage>=b.maxMileage)return {state:'已到期',reason:'已达到模拟合同里程限制'};if(b.limit!==null&&b.used===null)return {state:'待核实',reason:'使用记录尚未核实'};if(b.limit!==null&&b.used>=b.limit)return {state:'已用尽',reason:'已达到合同次数限制'};if(!b.verifiedAt||s.now-b.verifiedAt>30*D)return {state:'待核实',reason:'缺少30天内的合同核实记录'};return {state:'已确认可用',reason:'仅限本车及所列项目，实际服务按适用条件确认'};}
export const benefitsFor=(s,vid)=>s.benefits.filter(b=>b.vehicle===vid);
export function queue(s,vid,kind){const v=vehicle(s,vid),l=access(s,v);const type=kind==='inspection'?'现车检查估价':'核实车辆权益';if(kind==='inspection'&&(v.tradeIntent!=='有意向'||l.life!=='活跃'||!l.allowed||v.rescueOpen))throw Error('需先确认置换意向、激活机会并解决进行中的救援');const old=M.tasksFor(s,l.id).find(t=>t.vehicle===vid&&t.serviceKind===kind);if(old)return old;const t=M.addTask(s,l,type,l.owner||'mgr',s.now+2*H,{domain:kind==='inspection'?'trade':'service',vehicle:vid,serviceKind:kind});M.event(s,l,'创建车主服务任务',`${v.model} · ${type}`,{vehicle:vid});return t;}
function completeTask(s,vid,kind,text){s.tasks.filter(t=>t.vehicle===vid&&t.serviceKind===kind&&M.isOpen(t)).forEach(t=>{t.status='已完成';t.completed=s.now;t.result=text;});}
export function verify(s,vid,{mileage,relation,note,usage}){const v=vehicle(s,vid),l=access(s,v);requireText(note,'核实依据');if(mileage===''||mileage===null||!Number.isFinite(Number(mileage))||Number(mileage)<0)throw Error('请提供有效的当前里程');if(relation!=='confirmed')throw Error('请核实当前车主关系');if(usage===''||!Number.isInteger(Number(usage))||Number(usage)<0)throw Error('请核实救援已使用次数');v.mileage=Number(mileage);v.mileageAt=s.now;v.relation=true;v.relationship='当前持有';v.updated=s.now;for(const b of benefitsFor(s,vid)){b.verifiedAt=s.now;b.verification=note;if(b.kind==='rescue')b.used=Number(usage);}completeTask(s,vid,'verify',note);M.event(s,l,'权益核实（演示）',note,{vehicle:vid});}
export function setIntent(s,vid,value,note){const v=vehicle(s,vid),l=access(s,v);if(!['有意向','暂不考虑'].includes(value))throw Error('请选择意向');requireText(note,'客户确认依据');if(value==='有意向'&&(!l.allowed||!l.valid||v.rescueOpen||v.relation!==true))throw Error('需确认车主关系、联系许可及服务问题已解决');v.tradeIntent=value;v.intentNote=note;v.intentAt=s.now;if(value==='暂不考虑')s.tasks.filter(t=>t.vehicle===vid&&t.domain==='trade'&&M.isOpen(t)).forEach(t=>{t.status='已取消';t.result='客户暂不考虑置换';});M.event(s,l,'确认置换意向',`${value} · ${note}`,{vehicle:vid});}
export function inspectVehicle(s,vid,note,value){const v=vehicle(s,vid),l=access(s,v);if(v.tradeIntent!=='有意向'||l.life!=='活跃'||!l.allowed||v.rescueOpen||v.relation!==true)throw Error('请先确认有效置换意向并激活机会');requireText(note,'检测及估值依据');if(value===''||!Number.isFinite(Number(value))||Number(value)<0)throw Error('请填写有效参考估值');v.inspection={at:s.now,note,value:Number(value),source:'人工模拟检查/估值，不是正式车况认证',actor:s.user};completeTask(s,vid,'inspection',note);M.event(s,l,'记录现车检查估价',note,{vehicle:vid});}
function amount(x){if(x===''||x===null||x===undefined)return null;const n=Number(x);if(!Number.isFinite(n)||n<0)throw Error('金额须为非负数字');return n;}
export function quoteMath(s,vid,values){const v=vehicle(s,vid);const price=amount(values.price),trade=amount(values.trade),fee=amount(values.fee);const benefit=values.benefit?s.benefits.find(b=>b.id===values.benefit&&b.vehicle===vid):null;if(values.benefit&&!benefit)throw Error('该权益不属于当前车辆');let deduction=0,reason='未选择抵扣项目';if(benefit){const st=benefitState(s,benefit);reason=st.state+' · '+st.reason;if(st.state==='已确认可用'&&benefit.kind==='inspection'&&fee!==null)deduction=Math.min(benefit.deduction,fee);}const complete=[price,trade,fee].every(n=>n!==null);const net=complete?price+fee-trade-deduction:null;return {price,trade,fee,deduction,net,reason,complete};}
export function createQuote(s,vid,f){const v=vehicle(s,vid),l=access(s,v);if(l.life!=='活跃'||!l.allowed||v.tradeIntent!=='有意向'||v.relation!==true||v.rescueOpen)throw Error('请先核实关系、确认置换意向并激活机会');requireText(f.basis,'价格依据与说明');requireText(f.target,'拟购车型');const amounts=quoteMath(s,vid,f);const q={id:'Q'+(++s.seq),vehicle:vid,lead:l.id,version:s.quotes.filter(q=>q.vehicle===vid).length+1,at:s.now,expires:s.now+7*D,createdBy:s.user,status:'参考草案',target:f.target,basis:f.basis,benefit:f.benefit||null,amounts,inspectionAt:v.inspection?.at||null,benefitSnapshot:f.benefit?structuredClone(s.benefits.find(b=>b.id===f.benefit)):null,currency:'CNY'};s.quotes.push(q);if(!M.tasksFor(s,l.id).some(t=>t.vehicle===vid&&t.serviceKind==='quote'))M.addTask(s,l,'复核置换方案',l.owner||'mgr',s.now+2*H,{domain:'trade',vehicle:vid,serviceKind:'quote'});M.event(s,l,'生成置换参考草案',`${q.id} / v${q.version} · ${f.target}`,{vehicle:vid});return q;}
export function quoteState(s,q){const v=vehicle(s,q.vehicle);if(s.quotes.some(n=>n.vehicle===q.vehicle&&n.version>q.version))return '历史版本';if(s.now>=q.expires)return '已过期';if(v.relation!==true||v.tradeIntent!=='有意向'||v.rescueOpen)return '待重新核实';if(q.amounts.deduction>0){const b=s.benefits.find(b=>b.id===q.benefit);if(!b||benefitState(s,b).state!=='已确认可用')return '权益变更待复核';}return q.status;}
export function confirmQuote(s,id,note){const q=s.quotes.find(q=>q.id===id);if(!q)throw Error('报价不存在');const v=vehicle(s,q.vehicle),l=access(s,v);if(s.user!=='mgr')throw Error('请切换主管复核');if(quoteState(s,q)!=='参考草案')throw Error('此版本已处理或需重新生成');if(!q.amounts.complete)throw Error('价格项目不完整，不能确认');if(l.life!=='活跃'||!l.allowed)throw Error('当前购车机会不能确认方案');if(!v.inspection||v.inspection.at!==q.inspectionAt||s.now-v.inspection.at>7*D)throw Error('需提供有效现车检查，并基于该检查重新生成草案');requireText(note,'复核说明');q.status='已复核（演示）';q.confirmedBy=s.user;q.confirmedAt=s.now;q.confirmation=note;completeTask(s,v.id,'quote',note);if(!M.tasksFor(s,l.id).some(t=>t.vehicle===v.id&&t.serviceKind==='explain'))M.addTask(s,l,'向客户解释置换方案',l.owner||'mgr',s.now+24*H,{domain:'trade',vehicle:v.id,serviceKind:'explain'});M.event(s,l,'复核置换方案（演示）',`${q.id} · ${note}`,{vehicle:v.id});}
export function explain(s,vid,note){const v=vehicle(s,vid),l=access(s,v);requireText(note,'客户沟通记录');completeTask(s,vid,'explain',note);M.event(s,l,'记录权益/方案说明',note,{vehicle:vid});}
